th)}{Algebra 2 \\textperiodcentered\\ Lesson 4-1 \\textperiodcentered\\ Period 3}\n  24: \\phasebadges{2}{12}{teacher models}\n  25: \\vspace{0.1cm}\n  26: \\begin{projcard}{Parent: \\(f(x) = 1/x\\)}{slidegreen}\n  27: \\begin{itemize}\n  28:   \\setlength{\\itemsep}{0pt}\n  29:   \\item V.A.: \\(x = 0\\) \\quad H.A.: \\(y = 0\\)\n  30:   \\item Domain: \\(x \\neq 0\\) \\quad Range: \\(y \\neq 0\\)\n  31:   \\item Hyperbola, Quadrants I and III. Never touches either axis.\n  32: \\end{itemize}\n  33: \\end{projcard}\n  34: \\vspace{-0.2cm}\n  35: \\begin{projcard}{Translated: \\(g(x) = 1/(x-h) + k\\)}{slidegreen}\n  36: \\begin{itemize}\n  37:   \\setlength{\\itemsep}{0pt}\n  38:   \\item V.A. \\(\\rightarrow x = h\\); H.A. \\(\\rightarrow y = k\\)\n  39:   \\item Domain: \\(x \\neq h\\) \\quad Range: \\(y \\neq k\\)\n  40:   \\item \\((h, k)\\) = \\textbf{new center} (where asymptotes cross)\n  41:   \\item \\textcolor{slideaccent}{Ex: \\(g(x) = 1/(x-3)+2\\) \\(\\rightarrow\\) asymptotes \\(x=3\\), \\(y=2\\)}\n  42: \\end{itemize}\n  43: \\end{projcard}\n  44: \\end{frame}\n  45: \n  46: % ==== Explore =============================================================\n  47: \\begin{frame}{Explore --- TPS: Parent Forms}{Algebra 2 \\textperiodcentered\\ Lesson 4-1 \\textperiodcentered\\ Period 3}\n  48: \\phasebadges{2}{35}{student work}\n  49: \\small\\textcolor{slidegray}{6 items total. Parent forms first (laps 1--3), then translations (laps 4--6).}\n  50: \n  51: \\vspace{0.1cm}\n  52: \\begin{projcard}{Try It 4 \\textperiodcentered\\ Scaled parent}{slideblue}\n  53: Graph \\(g(x) = 10/x\\). State domain, range, and asymptotes.\n  54: \\end{projcard}\n  55: \\vspace{-0.2cm}\n  56: \\begin{projcard}{Practice \\#11 \\textperiodcentered\\ Error Analysis: \\(y = 5/x\\)}{slideblue}\n  57: Describe and correct the student's graphing error.\n  58: \\end{projcard}\n  59: \\vspace{-0.2cm}\n  60: \\begin{projcard}{Practice \\#18 \\textperiodcentered\\ Reflected parent: \\(y = -2/x\\)}{slideblue}\n  61: Graph \\(y = -2/x\\). State domain, range, and asymptotes.\n  62: \\end{projcard}\n  63: \\end{frame}\n  64: \n  65: % ==== Explore (translations) ===============================================\n  66: \\begin{frame}{Explore --- TPS: Translations}{Algebra 2 \\textperiodcentered\\ Lesson 4-1 \\textperiodcentered\\ Period 3}\n  67: \\phasebadges{2}{35}{student work (cont.)}\n  68: \\small\\textcolor{slidegray}{Before each translation: identify \\((h,k)\\), state asymptotes, then graph.}\n  69: \n  70: \\vspace{0.1cm}\n  71: \\begin{projcard}{Try It 5 \\textperiodcentered\\ Translated: \\(g(x) = 1/(x+2) - 4\\)}{slideblue}\n  72: Graph \\(g(x) = 1/(x+2) - 4\\). Equations of asymptotes? Domain and range?\n  73: \\end{projcard}\n  74: \\vspace{-0.2cm}\n  75: \\begin{projcard}{Practice \\#19 \\textperiodcentered\\ \\(\\bigstar\\) ASSESSMENT CRITICAL}{slideaccent}\n  76: \\(g(x) = 1/(x-2) + 6\\). Asymptotes, domain, range, \\textbf{and intercepts}. (\\(\\sim\\)8 min)\n  77: \\end{projcard}\n  78: \\vspace{-0.2cm}\n  79: \\begin{projcard}{Practice \\#21 \\textperiodcentered\\ Video game storage (if time)}{slideblue}\n  80: Number of games \\(n\\) varies inversely with average game size \\(s\\) (GB).\n  81: \\end{projcard}\n  82: \\end{frame}\n  83: \n  84: % ==== Share / Summary =====================================================\n  85: \\begin{frame}{Share / Summary --- Concept Wrap + Assessment Preview}{Algebra 2 \\textperiodcentered\\ Lesson 4-1 \\textperiodcentered\\ Period 3}\n  86: \\phasebadges{2}{5}{DOK-2 reveal + LEHS preview}\n  87: \\vspace{0.1cm}\n  88: \\begin{projcard}{Sentence frame \\textperiodcentered\\ Practice \\#19 pair share}{slideblue}\n  89: \\small\n  90: ``This graph is the parent \\(f(x) = 1/x\\) translated \\underline{\\hspace{0.8cm}} units \\underline{\\hspace{0.8cm}} and \\underline{\\hspace{0.8cm}} units \\underline{\\hspace{0.8cm}}.\n  91: The asymptotes are \\(x =\\) \\underline{\\hspace{0.5cm}} and \\(y =\\) \\underline{\\hspace{0.5cm}}.\n  92: The intercepts are \\underline{\\hspace{1.8cm}}.''\n  93: \\end{projcard}\n  94: \n  95: \\vspace{-0.1cm}\n  96: \\begin{projcard}{\\(\\bigstar\\) Assessment Signal --- Topic 4 LEHS Q\\#3 + Q\\#5}{slideaccent}\n  97: \\small\n  98: \\begin{itemize}\n  99:   \\setlength{\\itemsep}{0pt}\n 100:   \\item \\textbf{Q\\#3}: H/V asymptotes --- you just rehearsed this in \\#19.\n 101:   \\item \\textbf{Q\\#5}: Translation description --- the sentence frame above IS the answer.\n 102:   \\item Practice \\#19 hit BOTH. You are ready.\n 103: \\end{itemize}\n 104: \\end{projcard}\n 105: \\end{frame}\n 106: \n 107: % ==== Exit Ticket =========================================================\n 108: \\begin{frame}{Exit Ticket --- Pre-Assessment Confidence Check}{Algebra 2 \\textperiodcentered\\ Lesson 4-1 \\textperiodcentered\\ Period 3}\n 109: \\phasebadges{1-2}{3}{not graded}\n 110: \\vspace{0.2cm}\n 111: \\begin{projcard}{Complete on your exit ticket}{slidegold}\n 112: \\begin{enumerate}\n 113:   \\setlength{\\itemsep}{0.2cm}\n 114:   \\item I can identify asymptotes of \\(y = 1/(x-h) + k\\). \\hfill Confidence: 1 / 2 / 3 / 4 / 5\n 115:   \\item I can describe a translation from \\(f(x) = 1/x\\) to \\(g(x)\\). \\hfill Confidence: 1 / 2 / 3 / 4 / 5\n 116:   \\item One thing I want to review before Topic 4 assessment: \\underline{\\hspace{3.5cm}}.\n 117: \\end{enumerate}\n 118: \\end{projcard}\n 119: \\end{frame}\n 120: \n 121: \\end{document}\n===== tex/L41_P2_slides.tex =====\n   1: \\documentclass[aspectratio=169, 14pt]{beamer}\n   2: \\usepackage{beamer_preamble}\n   3: \n   4: \\begin{document}\n   5: \n   6: % ==== Title ===============================================================\n   7: \\titleslide{Lesson 4-1 \\textperiodcentered\\ Period 2}{Inverse Variation Applications + DOK-3 Performance Task}\n   8: \n   9: % ==== Do Now ==============================================================\n  10: \\begin{frame}{Do Now --- Is this inverse variation?}{Algebra 2 \\textperiodcentered\\ Lesson 4-1 \\textperiodcentered\\ Period 2}\n  11: \\phasebadges{1}{5}{bridge from P1}\n  12: \\vspace{0.2cm}\n  13: \\begin{projcard}{Practice \\#15 \\textperiodcentered\\ Table check}{slidegold}\n  14: \\begin{tabular}{l|cccccc}\n  15: \\(x\\) & 1 & 2 & 3 & 4 & 5 & 6 \\\\\n  16: \\(y\\) & 60 & 30 & 20 & 15 & 12 & 10 \\\\\n  17: \\end{tabular}\n  18: \n  19: \\vspace{0.25cm}\n  20: Is this an inverse variation? Compute \\(xy\\) for each column.\n  21: If yes, state \\(k\\).\n  22: \\end{projcard}\n  23: \\end{frame}\n  24: \n  25: % ==== Launch ==============================================================\n  26: \\begin{frame}{Launch --- Example 3 (Bouzouki)}{Algebra 2 \\textperiodcentered\\ Lesson 4-1 \\textperiodcentered\\ Period 2}\n  27: \\phasebadges{2}{12}{teacher models}\n  28: \\vspace{0.2cm}\n  29: \\begin{projcard}{Application Rules for Inverse Variation}{slidegreen}\n  30: \\begin{enumerate}\n  31:   \\setlength{\\itemsep}{0pt}\n  32:   \\item Identify two varying quantities and their constant PRODUCT \\(k\\).\n  33:   \\item Compute \\(k\\) from one given pair.\n  34:   \\item Write the equation \\(y = k/x\\) (rename variables to fit).\n  35:   \\item Solve for the unknown.\n  36: \\end{enumerate}\n  37: \n  38: \\vspace{0.1cm}\n  39: \\small\n  40: Example (bouzouki string): length \\(s\\) varies inversely with frequency \\(f\\).\\\\\n  41: \\hspace*{1em}\\(\\bullet\\) 26-inch string \\(\\rightarrow\\) 329.63 cycles/sec \\(\\rightarrow\\) \\(k = 8{,}570.38\\)\\\\\n  42: \\hspace*{1em}\\(\\bullet\\) 13-inch string \\(\\rightarrow\\) \\(f = 8{,}570.38 / 13 = 659.26\\) cycles/sec\n  43: \n  44: \\vspace{0.1cm}\n  45: \\textcolor{slideaccent}{\\textbf{DIRECT (\\(y/x = k\\)) vs INVERSE (\\(xy = k\\))} --- both appear in today's DOK-3!}\n  46: \\end{projcard}\n  47: \\end{frame}\n  48: \n  49: % ==== Explore =============================================================\n  50: \\begin{frame}{Explore --- TPS + DOK-3 Performance Task}{Algebra 2 \\textperiodcentered\\ Lesson 4-1 \\textperiodcentered\\ Period 2}\n  51: \\phasebadges{2-3}{33}{student work}\n  52: \\small\\textcolor{slidegray}{5 items in order. Plan \\(\\sim\\)15 min for Practice \\#26 (Ram\u00c3\u00b3n).}\n  53: \n  54: \\vspace{0.15cm}\n  55: \\begin{projcard}{Try It 3 \\textperiodcentered\\ Ice cube melting}{slideblue}\n  56: Time to melt varies inversely with air temperature.\n  57: \\end{projcard}\n  58: \\vspace{-0.15cm}\n  59: \\begin{projcard}{Practice \\#12 \\textperiodcentered\\ HOT: inverse SQUARE}{slideblue}\n  60: \\(y = k/x^2\\). If \\(x\\) is multiplied by 4, what happens to \\(y\\)?\n  61: \\end{projcard}\n  62: \\vspace{-0.15cm}\n  63: \\begin{projcard}{Practice \\#17 \\textperiodcentered\\ Radio wavelength (graph)}{slideblue}\n  64: \\(w\\) varies inversely with frequency \\(f\\). Find \\(f\\) when \\(w = 375\\) m.\n  65: \\end{projcard}\n  66: \\vspace{-0.15cm}\n  67: \\begin{projcard}{Practice \\#23 \\textperiodcentered\\ Boyle's Law}{slideblue}\n  68: Volleyball 300 in\\(^3\\) at 4.5 psi vs basketball 415 in\\(^3\\) at 8 psi.\n  69: \\end{projcard}\n  70: \\vspace{-0.15cm}\n  71: \\begin{projcard}{Practice \\#26 \\textperiodcentered\\ PERFORMANCE TASK (\\(\\bigstar\\))}{slideaccent}\n  72: Ram\u00c3\u00b3n's road trip --- Part A is \\textbf{DIRECT}, Part B is \\textbf{INVERSE}.\n  73: \\end{projcard}\n  74: \\end{frame}\n  75: \n  76: % ==== Share / Summary =====================================================\n  77: \\begin{frame}{Share / Summary}{Algebra 2 \\textperiodcentered\\ Lesson 4-1 \\textperiodcentered\\ Period 2}\n  78: \\phasebadges{2}{5}{DOK-3 reveal + Wed bridge}\n  79: \\vspace{0.2cm}\n  80: \\begin{projcard}{Sentence frame \\textperiodcentered\\ Ram\u00c3\u00b3n}{slideblue}\n  81: ``Part A is \\underline{\\hspace{1cm}} variation because distance and time\n  82: have a constant \\textbf{RATIO} of \\underline{\\hspace{1cm}}.\\\\\n  83: Part B is \\underline{\\hspace{1cm}} variation because gas and time have\n  84: a constant \\textbf{PRODUCT} of \\underline{\\hspace{1cm}}.''\n  85: \\end{projcard}\n  86: \n  87: \\vspace{0.15cm}\n  88: \\begin{projcard}{Bridge to Period 3 (Wednesday)}{slideaccent}\n  89: Tomorrow we graph \\(y = 1/x\\) and its translations.\n  90: Watch for: asymptotes, domain, range, intercepts.\n  91: Period 3 is \\textbf{assessment-critical} for the Topic 4 8-Q assessment.\n  92: \\end{projcard}\n  93: \\end{frame}\n  94: \n  95: % ==== Exit Ticket =========================================================\n  96: \\begin{frame}{Exit Ticket --- Summary Recap}{Algebra 2 \\textperiodcentered\\ Lesson 4-1 \\textperiodcentered\\ Period 2}\n  97: \\phasebadges{1-2}{3}{not graded}\n  98: \\vspace{0.2cm}\n  99: \\begin{projcard}{Complete on your exit ticket}{slidegold}\n 100: \\begin{enumerate}\n 101:   \\setlength{\\itemsep}{0.2cm}\n 102:   \\item Today I learned that \\underline{\\hspace{5cm}}.\n 103:   \\item The biggest trap in Ram\u00c3\u00b3n's task was \\underline{\\hspace{5cm}}.\n 104:   \\item I distinguish direct from inverse variation by \\underline{\\hspace{5cm}}.\n 105: \\end{enumerate}\n 106: \\end{projcard}\n 107: \\end{frame}\n 108: \n 109: \\end{document}\n===== tex/L41_P3_student.tex =====\n   1: \\documentclass[11pt]{article}\n   2: \\usepackage{preamble}\n   3: \n   4: \\newcommand{\\IconChart}{[CHART]}\n   5: \\newcommand{\\entrybox}{\\framebox[1.2em]{\\rule{0pt}{0.95em}}}\n   6: \\newcommand{\\reciprocalblankgrid}{%\n   7: \\begin{center}\n   8: \\begin{tikzpicture}\n   9: \\begin{axis}[\n  10:   width=0.78\\linewidth,\n  11:   height=2.15in,\n  12:   xmin=-10, xmax=10,\n  13:   ymin=-10, ymax=10,\n  14:   axis lines=middle,\n  15:   grid=both,\n  16:   minor tick num=4,\n  17:   xtick={-10,-5,0,5,10},\n  18:   ytick={-10,-5,0,5,10},\n  19:   tick label style={font=\\small},\n  20:   label style={font=\\small},\n  21:   major grid style={draw=black!25},\n  22:   minor grid style={draw=black!10},\n  23:   xlabel