                                             \\n-a----         4/21/2026  10:03 AM          38947 L63_P1_Slides.pptx                                                   \\n-a----         4/21/2026   9:11 PM          40342 L63_P1_Student_Packet.docx                                           \\n-a----         4/21/2026   9:11 PM          43542 L63_P1_Teacher_Packet.docx                                           \\n-a----         4/21/2026   9:11 PM            569 L63_P1_Visuals_Checklist.md                                          \\n-a----         4/21/2026  10:03 AM          15878 L63_Pacer.html                                                       \\n-a----         4/21/2026   9:11 PM          38735 L64_P1_Do_Now.docx                                                   \\n-a----         4/21/2026  10:03 AM          38780 L64_P1_Slides.pptx                                                   \\n-a----         4/21/2026   9:11 PM          40440 L64_P1_Student_Packet.docx                                           \\n-a----         4/21/2026   9:11 PM          43630 L64_P1_Teacher_Packet.docx                                           \\n-a----         4/21/2026   9:11 PM            868 L64_P1_Visuals_Checklist.md                                          \\n-a----         4/21/2026  10:03 AM          14421 L64_Pacer.html                                                       \\n-a----         4/21/2026   9:11 PM          38564 L65_P1_Do_Now.docx                                                   \\n-a----         4/21/2026  10:03 AM          38625 L65_P1_Slides.pptx                                                   \\n-a----         4/21/2026   9:11 PM          40585 L65_P1_Student_Packet.docx                                           \\n-a----         4/21/2026   9:11 PM          43605 L65_P1_Teacher_Packet.docx                                           \\n-a----         4/21/2026   9:11 PM            358 L65_P1_Visuals_Checklist.md                                          \\n-a----         4/21/2026  10:03 AM          15009 L65_Pacer.html                                                       \\n-a----         4/21/2026  10:03 AM           2416 Lesson_4-1_Visuals_Checklist.md                                      \\n-a----         4/21/2026  10:03 AM         268329 lesson_4-4_rational_expressions.pdf                                  \\n-a----         4/21/2026  10:03 AM          14991 lesson_4-4_rational_expressions.tex                                  \\n-a----         4/21/2026  10:03 AM         132373 lupe-carnival.png                                                    \\n-a----         4/21/2026   5:53 PM           3029 merge_tags.py                                                        \\n-a----         4/21/2026   9:06 PM           4832 packet_build.py                                                      \\n-a----         4/21/2026  10:03 AM          25205 packet_styles.py                                                     \\n-a----         4/21/2026  10:03 AM           9654 qb.py                                                                \\n-a----         4/21/2026   2:57 PM           6349 qb_append.py                                                         \\n-a----         4/21/2026   8:24 PM          14182 qb_diagnose.py                                                       \\n-a----         4/21/2026   3:10 PM          12867 qb_graph.py                                                          \\n-a----         4/21/2026   8:25 PM          14793 qb_polish_worksheet.py                                               \\n-a----         4/16/2026   8:33 PM            152 README.md                                                            \\n-a----         4/21/2026   9:13 PM           7257 refactor_builders_to_packet_build.py                                 \\n-a----         4/21/2026   2:36 PM           4216 SCHEMA_V2_PROPOSAL.md                                                \\n-a----         4/21/2026  10:03 AM         261424 topic5AsserssAnswer.pdf                                              \\n-a----         4/21/2026  10:03 AM        2097659 topic5Assess.docx                                                    \\n-a----         4/21/2026  10:03 AM           9604 topic5_assessment_formB.tex                                          \\n-a----         4/21/2026  10:03 AM        1275380 Topic6Assess.docx                                                    \\n-a----         4/21/2026  10:03 AM         228691 Topic6AssessAnswer.pdf                                               \\n-a----         4/21/2026  10:03 AM         191794 Topic6AssessFormB.pdf                                                \\n-a----         4/21/2026  10:03 AM           8924 Topic6AssessFormB.tex                                                \\n-a----         4/21/2026  10:03 AM          24387 WIKI_UPDATES_PENDING.md                                              \\n\\n\\n\\ncodex\\nI\\u2019ve confirmed the target files and there\\u2019s no `tex/` directory yet. Next I\\u2019m extracting the lesson anchors from the eye-check brief and the referenced question-bank items so the LaTeX packet preserves the required wording and order.\\nexec\\n\\\"C:\\\\\\\\Windows\\\\\\\\System32\\\\\\\\WindowsPowerShell\\\\\\\\v1.0\\\\\\\\powershell.exe\\\" -Command 'Get-Content -Raw build_L41_P2_packets.py' in C:\\\\Users\\\\rober\\\\Downloads\\\\Projects\\\\Lesson_planning\\nexec\\n\\\"C:\\\\\\\\Windows\\\\\\\\System32\\\\\\\\WindowsPowerShell\\\\\\\\v1.0\\\\\\\\powershell.exe\\\" -Command \\\"Get-Content -Raw graph\\\\\\\\eye_check\\\\\\\\L41_P2.md\\\" in C:\\\\Users\\\\rober\\\\Downloads\\\\Projects\\\\Lesson_planning\\nexec\\n\\\"C:\\\\\\\\Windows\\\\\\\\System32\\\\\\\\WindowsPowerShell\\\\\\\\v1.0\\\\\\\\powershell.exe\\\" -Command 'Get-Content -Raw packet_styles.py' in C:\\\\Users\\\\rober\\\\Downloads\\\\Projects\\\\Lesson_planning\\nexec\\n\\\"C:\\\\\\\\Windows\\\\\\\\System32\\\\\\\\WindowsPowerShell\\\\\\\\v1.0\\\\\\\\powershell.exe\\\" -Command 'Get-Content -Raw packet_build.py' in C:\\\\Users\\\\rober\\\\Downloads\\\\Projects\\\\Lesson_planning\\n succeeded in 498ms:\\n\\\"\\\"\\\"Generate Lesson 4-1 Period 2 materials \\u00e2\\u20ac\\u201d Klimsara-adapted, no Blooket.\\n\\nDesign: Inverse variation applications + the lesson's single-DOK-3 spine.\\nP2 is the conceptual core: students apply y = k/x to real contexts, then\\ntackle the Ram\\u00c3\\u00b3n performance task (#26) which contrasts DIRECT vs INVERSE\\nvariation \\u00e2\\u20ac\\u201d the pedagogical anchor of the whole lesson.\\n\\nPhases (55 min base; Period F 65-min):\\n  0\\u00e2\\u20ac\\u201c  5   Do Now    : Practice #15 \\u00e2\\u20ac\\u201d quick table-check of inverse variation [DOK 1]\\n  5\\u00e2\\u20ac\\u201c 17   Launch    : teacher models Example 3 (bouzouki string / frequency) [DOK 2]\\n 17\\u00e2\\u20ac\\u201c 50   Explore   : Try-It 3 + Practice #12/#17/#23 + \\u00e2\\u00ad\\u0090 DOK-3 q26 (Ram\\u00c3\\u00b3n) [DOK 2-3]\\n 50\\u00e2\\u20ac\\u201c 55   Share/Sum : DOK-3 pair presents + Wed bridge to reciprocal function [DOK 2]\\n 55\\u00e2\\u20ac\\u201c 58   Exit      : summary recap fill-in                                  [DOK 1-2]\\n (back)   Optional: Practice #25 (SAT/ACT MC DOK-3) \\u00e2\\u20ac\\u201d fast-finisher stretch\\n\\\"\\\"\\\"\\nimport sys, io\\nsys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8', errors='replace')\\n\\nimport qb\\nimport packet_styles as ps\\nfrom packet_build import (\\n    TABLE_STYLE, new_packet_doc,\\n    set_cell, add_callout, bank_item_block, add_header_block,\\n)\\n\\nDO_NOW_ID   = \\\"4-1-savvas-q15\\\"\\nEXPLORE_IDS = [\\n    \\\"4-1-savvas-try-it-3-lesson-4-1-matches-examp\\\",\\n    \\\"4-1-savvas-q12\\\",        # HOT \\u00e2\\u20ac\\u201d inverse square\\n    \\\"4-1-savvas-q17\\\",        # wavelength/frequency graph\\n    \\\"4-1-savvas-q23\\\",        # Boyle's Law\\n    \\\"4-1-savvas-q26\\\",        # \\u00e2\\u00ad\\u0090 DOK-3 spine \\u00e2\\u20ac\\u201d Ram\\u00c3\\u00b3n (direct vs inverse)\\n]\\nDOK3_ID       = \\\"4-1-savvas-q26\\\"\\nREINFORCE_IDS = [\\\"4-1-savvas-q25\\\"]   # SAT/ACT MC DOK-3 stretch\\n\\n_ALL_IDS = [DO_NOW_ID] + EXPLORE_IDS + REINFORCE_IDS\\nqb.get_for_packet(_ALL_IDS)\\n\\nLESSON_LABEL = \\\"Lesson 4-1 \\u00c2\\u00b7 Period 2\\\"\\nLESSON_TITLE = \\\"Inverse Variation Applications + DOK-3 Performance Task\\\"\\n\\nOBJECTIVES = [\\n    (\\\"Math Objective\\\",\\n     \\\"Apply inverse variation to real-world contexts (wavelength, gas pressure, \\\"\\n     \\\"travel distance), and distinguish DIRECT variation (y = kx) from INVERSE \\\"\\n     \\\"variation (xy = k) inside a single multi-part problem.\\\"),\\n    (\\\"Language Objective\\\",\\n     \\\"Students will use the frame \\\\u201cThis is ___ variation because as ___ \\\"\\n     \\\"___, ___ ___ proportionally.\\\\u201d to justify whether a relationship is \\\"\\n     \\\"direct or inverse.\\\"),\\n    (\\\"Essential Understanding\\\",\\n     \\\"Not every covariation is inverse variation. Direct variation has a \\\"\\n     \\\"constant RATIO (y/x = k); inverse variation has a constant PRODUCT \\\"\\n     \\\"(xy = k). A single scenario can contain BOTH types across different \\\"\\n     \\\"variable pairs.\\\"),\\n]\\n\\nFRAMEWORK_HEADER = [\\n    (\\\"Topic Goals\\\",\\n     \\\"Students model 4 contextual inverse-variation problems, then tackle a \\\"\\n     \\\"Performance Task (Ram\\u00c3\\u00b3n's road trip) that embeds direct and inverse \\\"\\n     \\\"variation in one scenario. Every item is Savvas-sourced.\\\"),\\n    (\\\"Essential Question\\\",\\n     \\\"How does inverse variation model real-world relationships, and how is \\\"\\n     \\\"it different from direct variation?\\\"),\\n    (\\\"Materials\\\",\\n     \\\"Pencils; student packet; calculator. No Chromebooks required.\\\"),\\n]\\n\\n\\n# \\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac Do Now \\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\n\\ndef _header(doc, *, for_teacher=False):\\n    add_header_block(doc, lesson_title=LESSON_TITLE, lesson_label=LESSON_LABEL,\\n                     objectives=OBJECTIVES, framework_header=FRAMEWORK_HEADER,\\n                     for_teacher=for_teacher)\\n\\n\\ndef build_do_now(path):\\n    doc = new_packet_doc(top=0.6, bottom=0.6, left=0.75, right=0.75)\\n    ps.running_header_name_block(doc, label_right=\\\"BLOCK\\\")\\n    ps.day_banner(doc, 2, \\\"Do Now \\u00e2\\u20ac\\u201d \\\" + LESSON_TITLE, subtitle=LESSON_LABEL)\\n\\n    ps.framework_phase_header(\\n        doc,\\n        phase=\\\"Do Now\\\",\\n        framework_tag=\\\"bridge from P1\\\",\\n        dok=\\\"1\\\",\\n        minutes=5,\\n        teacher_does=[\\\"Hand out at door.\\\", \\\"Circulate 3 min.\\\",\\n                      \\\"Cold-call 1 student: \\\\\\\"Is this table inverse? What's k?\\\\\\\"\\\"],\\n        students_do=[\\\"Compute xy for each column.\\\",\\n                     \\\"If constant \\u00e2\\u2020\\u2019 inverse; state k. If not \\u00e2\\u2020\\u2019 not inverse.\\\"],\\n        questions_to_ask=[\\n            \\\"What do you multiply to check for inverse variation?\\\",\\n            \\\"What would make this NOT inverse? (xy not constant.)\\\",\\n        ],\\n        adult_role=\\\"Solo teacher: circulate, time 5 min, pull sheets.\\\",\\n    )\\n\\n    q = qb.get_for_packet([DO_NOW_ID])[0]\\n    bank_item_block(doc, q, label=\\\"Do Now \\u00e2\\u20ac\\u201d Is this inverse variation?\\\",\\n                    space_after_inches=2.0)\\n\\n    add_callout(doc, \\\"\\u00f0\\u0178\\u017d\\u00af  SENTENCE FRAME\\\",\\n                [\\\"\\\\u201cThe product xy is ___ for every pair, so this ___ (is / is not) an inverse variation. The constant of variation is ___.\\\\u201d\\\"],\\n                color_hex=\\\"FFF2CC\\\")\\n\\n    doc.save(path)\\n\\n\\n# \\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac Student packet \\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\n\\ndef build_student(path):\\n    doc = new_packet_doc(top=0.55, bottom=0.55, left=0.7, right=0.7)\\n\\n    _header(doc, for_teacher=False)\\n\\n    ps.teal_section(doc, \\\"LAUNCH \\u00e2\\u20ac\\u201d Inverse Variation in Context (teacher models Example 3)\\\", [])\\n    add_callout(doc, \\\"\\u00f0\\u0178\\u201c\\u02dc  APPLICATION RULES (keep printed on your page)\\\",\\n                [\\n                    \\\"\\u00e2\\u20ac\\u00a2 To model an inverse variation in context:\\\",\\n                    \\\"     1. Identify the two varying quantities and their constant product k.\\\",\\n                    \\\"     2. Compute k from one given pair: k = (quantity 1) \\u00c3\\u2014 (quantity 2).\\\",\\n                    \\\"     3. Write the equation: y = k/x (or rename variables to fit the context).\\\",\\n                    \\\"     4. Solve for the unknown quantity.\\\",\\n                    \\\"\\u00e2\\u20ac\\u00a2 Example (Savvas Ex 3, bouzouki): string length s varies inversely with frequency f.\\\",\\n                    \\\"     26-inch string \\u00e2\\u2020\\u2019 329.63 cycles/sec \\u00e2\\u2020\\u2019 k = 26 \\u00c3\\u2014 329.63 = 8,570.38.\\\",\\n                    \\\"     New length 13 inches \\u00e2\\u2020\\u2019 f = 8,570.38 / 13 = 659.26 cycles/sec.\\\",\\n                ],\\n                color_hex=\\\"D9EAD3\\\")\\n\\n    add_callout(doc, \\\"\\u00e2\\u0161\\u00a0\\u00ef\\u00b8\\u008f  DIRECT vs INVERSE (both appear in today's DOK-3!)\\\",\\n                [\\n                    \\\"DIRECT: y = kx \\u00e2\\u2020\\u2019 y/x is constant. As x increases, y INCREASES proportionally.\\\",\\n                    \\\"INVERSE: y = k/x (xy = k). As x increases, y DECREASES proportionally.\\\",\\n                    \\\"Test: compute y/x (direct) AND xy (inverse). Whichever is constant tells you the relationship.\\\",\\n                ],\\n                color_hex=\\\"F4CCCC\\\")\\n    doc.add_paragraph()\\n\\n    ps.teal_section(doc, \\\"EXPLORE \\u00e2\\u20ac\\u201d Think-Pair-Share (33 min)\\\",\\n                    [\\\"Work with a partner. Move in order. Practice #26 (Ram\\u00c3\\u00b3n) is the big one \\u00e2\\u20ac\\u201d plan ~15 min for it.\\\"])\\n\\n    items = qb.get_for_packet(EXPLORE_IDS)\\n    labels = [\\n        \\\"Try It 3 \\u00e2\\u20ac\\u201d Ice cube melting\\\",\\n        \\\"Practice #12 \\u00e2\\u20ac\\u201d HOT: inverse SQUARE variation\\\",\\n        \\\"Practice #17 \\u00e2\\u20ac\\u201d Radio wavelength (graph)\\\",\\n        \\\"Practice #23 \\u00e2\\u20ac\\u201d Boyle's Law (volleyball vs basketball)\\\",\\n        \\\"Practice #26  \\u00e2\\u00ad\\u0090 PERFORMANCE TASK \\u00c2\\u00b7 Ram\\u00c3\\u00b3n's road trip\\\",\\n    ]\\n    for label, q in zip(labels, items):\\n        bank_item_block(doc, q, label=label, space_after_inches=1.5)\\n\\n    ps.teal_section(doc, \\\"SHARE / SUMMARY (5 min)\\\", [])\\n    ps.sentence_frame_box(doc, [\\n        \\\"Pair share (Ram\\u00c3\\u00b3n task): \\\\u201cPart A is ___ variation because distance and time have a constant RATIO of ___. Part B is ___ variation because gas and time have a constant PRODUCT of ___.\\\\u201d\\\",\\n        \\\"Whole class: one pair reads the contrast. Class signals thumbs up/sideways.\\\",\\n    ])\\n\\n    add_callout(doc, \\\"\\u00f0\\u0178\\u201d\\u00ad  BRIDGE TO P3 (Wednesday)\\\",\\n                [\\\"Tomorrow we graph the RECIPROCAL FUNCTION y = 1/x and its translations. Watch for: the graph of inverse variation has asymptotes and a specific shape \\u00e2\\u20ac\\u201d a hyperbola. You've been drawing them already; we'll name the features.\\\"],\\n                color_hex=\\\"FCE5CD\\\")\\n\\n    ps.summary_exit_box(doc, \\\"EXIT TICKET \\u00e2\\u20ac\\u201d Summary Recap\\\",\\n                        [\\n                            \\\"Today I learned that _____________________________________________________.\\\",\\n                            \\\"The biggest trap in Ram\\u00c3\\u00b3n's task was _____________________________________________________.\\\",\\n                            \\\"I distinguish direct from inverse variation by _____________________________________________________.\\\",\\n                        ])\\n\\n    doc.add_page_break()\\n    ps.teal_section(doc, \\\"OPTIONAL REINFORCEMENT (not collected)\\\",\\n                    [\\\"If you finish Explore early. #25 is a fast SAT-style question that stretches the inverse-variation idea.\\\"])\\n    reinforce = qb.get_for_packet(REINFORCE_IDS)\\n    for i, q in enumerate(reinforce, 1):\\n        bank_item_block(doc, q, label=f\\\"Optional #{i}  (Savvas Practice, SAT/ACT style)\\\",\\n                        space_after_inches=1.8)\\n\\n    doc.save(path)\\n\\n\\n# \\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac Teacher packet \\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\u00e2\\u201d\\u20ac\\n\\ndef build_teacher(path):\\n    doc = new_packet_doc(top=0.5, bottom=0.5, left=0.7, right=0.7)\\n\\n    _header(doc, for_teacher=True)\\n\\n    add_callout(doc, \\\"\\u00f0\\u0178\\u201c\\u0152  PRE-FLIGHT \\u00e2\\u20ac\\u201d P2 IS THE DOK-3 SPINE DAY\\\",\\n                [\\n                    \\\"Today's conceptual core is Practice #26 (Ram\\u00c3\\u00b3n). Part A is direct variation, Part B is inverse \\u00e2\\u20ac\\u201d same scenario, different variable pairs. That contrast IS the lesson's deepest content.\\\",\\n                    \\\"Pace: Try-It 3 (5 min) \\u00e2\\u2020\\u2019 #12 (4 min) \\u00e2\\u2020\\u2019 #17 (5 min) \\u00e2\\u2020\\u2019 #23 (7 min) \\u00e2\\u2020\\u2019 #26 (12-15 min). ~33-36 min total Explore.\\\",\\n                    \\\"If running tight: cut #12 (the HOT inverse-square is tangent, not central). Never cut #26.\\\",\\n                ],\\n                color_hex=\\\"FFD9E0\\\")\\n\\n    ps.framework_phase_header(\\n        doc,\\n        phase=\\\"Do Now\\\",\\n        framework_tag=\\\"bridge from P1\\\",\\n        dok=\\\"1\\\",\\n        minutes=5,\\n        teacher_does=[\\\"Hand out at door.\\\", \\\"Circulate 3 min.\\\",\\n                      \\\"Cold-call 1 student for xy computation.\\\"],\\n        students_do=[\\\"Compute xy for each column.\\\",\\n                     \\\"State k if constant; explain if not.\\\"],\\n        questions_to_ask=[\\n            \\\"What do you multiply to check inverse variation?\\\",\\n            \\\"Is xy constant here? What does that tell you?\\\",\\n        ],\\n        adult_role=\\\"Solo teacher: circulate silently. No hints.\\\",\\n    )\\n    q = qb.get_for_packet([DO_NOW_ID])[0]\\n    bank_item_block(doc, q, label=f\\\"Do Now ({q['id']})\\\", space_after_inches=0.3)\\n    add_callout(doc, \\\"\\u00e2\\u0153\\u2026  ANSWER KEY\\\",\\n                [q.get(\\\"notes\\\") or \\\"(verify)\\\"],\\n                color_hex=\\\"D9EAD3\\\")\\n\\n    ps.framework_phase_header(\\n        doc,\\n        phase=\\\"Launch\\\",\\n        framework_tag=\\\"teacher models Example 3\\\",\\n        dok=\\\"2\\\",\\n        minutes=12,\\n        teacher_does=[\\n            \\\"Project Example 3 (bouzouki). Think aloud: extract the two quantities (s = string length, f = frequency). Compute k = sf.\\\",\\n            \\\"\\\\\\\"Now I can find f for any s. Plug in the new length, solve.\\\\\\\"\\\",\\n            \\\"Flag the Application Rules card \\u00e2\\u20ac\\u201d print it in student minds.\\\",\\n            \\\"30-sec pause: \\\\\\\"What's k for YOUR Do Now table?\\\\\\\" (partner check)\\\",\\n            \\\"Do NOT solve Try-It 3 or Practice items \\u00e2\\u20ac\\u201d release at minute 17.\\\",\\n        ],\\n        students_do=[\\n            \\\"Watch the bouzouki example silently.\\\",\\n            \\\"During pause: state k from Do Now to partner.\\\",\\n            \\\"Copy Application Rules card into margin.\\\",\\n            \\\"Note the DIRECT vs INVERSE warning: this comes back in #26.\\\",\\n        ],\\n        questions_to_ask=[\\n            \\\"What two quantities are related? What's constant?\\\",\\n            \\\"\\\\\\\"Every radio wave with frequency f has wavelength w such that wf = constant.\\\\\\\" Why is that inverse?\\\",\\n            \\\"If frequency doubles, what happens to wavelength? Why?\\\",\\n        ],\\n        adult_role=\\\"Project. Think aloud. Release promptly at minute 17.\\\",\\n    )\\n    add_callout(doc, \\\"\\u00f0\\u0178\\u017d\\u00a4  TEACHER SCRIPT\\\",\\n                [\\n                    \\\"1. \\\\u201cWatch me set up a real-world inverse variation. Bouzouki string: length s varies inversely with frequency f.\\\\u201d\\\",\\n                    \\\"2. \\\\u201cStep 1: Identify the quantities and find k. k = sf = 26 \\u00c3\\u2014 329.63 = 8,570.38.\\\\u201d\\\",\\n                    \\\"3. \\\\u201cStep 2: Write the equation. s = k/f, so s = 8570.38/f.\\\\u201d\\\",\\n                    \\\"4. \\\\u201cStep 3: Plug in the new value. For s = 13: f = 8570.38/13 = 659.26 cycles/sec.\\\\u201d\\\",\\n                    \\\"5. \\\\u201cTonight's Performance Task has a twist \\u00e2\\u20ac\\u201d ONE scenario contains BOTH direct and inverse variation. Be ready to tell them apart.\\\\u201d\\\",\\n                    \\\"6. Release to Explore.\\\",\\n                ],\\n                color_hex=\\\"CFE2F3\\\")\\n\\n    ps.framework_phase_header(\\n        doc,\\n        phase=\\\"Explore\\\",\\n        framework_tag=\\\"TPS + DOK-3 driver\\\",\\n        dok=\\\"2-3\\\",\\n        minutes=33,\\n        teacher_does=[\\n            \\\"5 laps across 33 min.\\\",\\n            \\\"Lap 1 (5 min): Try-It 3 \\u00e2\\u20ac\\u201d ice cube. Press pairs to identify k = Temp \\u00c3\\u2014 Time.\\\",\\n            \\\"Lap 2 (4 min): #12 \\u00e2\\u20ac\\u201d inverse square. This is a THINKING item; let pairs struggle.\\\",\\n            \\\"Lap 3 (5 min): #17 \\u00e2\\u20ac\\u201d graph reading + context. Confirm k = 300,000.\\\",\\n            \\\"Lap 4 (7 min): #23 \\u00e2\\u20ac\\u201d Boyle's Law. Check that pairs compute volleyball's k = 1350.\\\",\\n            \\\"Lap 5 (12 min): \\u00e2\\u00ad\\u0090 #26 Ram\\u00c3\\u00b3n. PART A is direct; PART B is inverse. Press hard on that contrast.\\\",\\n            \\\"Do NOT give #26 answers. Pairs present Part A/B to each other; one pair presents at Share.\\\",\\n        ],\\n        students_do=[\\n            \\\"5 items in order: Try-It 3 \\u00e2\\u2020\\u2019 #12 \\u00e2\\u2020\\u2019 #17 \\u00e2\\u2020\\u2019 #23 \\u00e2\\u2020\\u2019 #26.\\\",\\n            \\\"For #26: BEFORE solving, identify which part is direct and which is inverse. Write it down.\\\",\\n            \\\"Justify with sentence frame.\\\",\\n        ],\\n        questions_to_ask=[\\n            \\\"What's k in this problem? What units?\\\",\\n            \\\"#12: y = k/x\\u00c2\\u00b2. If x \\u00e2\\u2020\\u2019 4x, what happens to y? (Divide by 16.)\\\",\\n            \\\"#17: from the graph, what's k? How do you read it?\\\",\\n            \\\"#23: Whose k do we use \\u00e2\\u20ac\\u201d the volleyball's, or the basketball's? (Volleyball's; the basketball only gives the target PRESSURE.)\\\",\\n            \\\"#26 Part A: is distance/time constant? \\u00e2\\u2020\\u2019 direct variation.\\\",\\n            \\\"#26 Part B: is gas \\u00c3\\u2014 time constant? \\u00e2\\u2020\\u2019 inverse variation.\\\",\\n        ],\\n        adult_role=\\\"Solo teacher: 5 laps. Press DIRECT vs INVERSE distinction on #26.\\\",\\n    )\\n    items = qb.get_for_packet(EXPLORE_IDS)\\n    labels = [\\n        \\\"Try It 3\\\", \\\"Practice #12\\\", \\\"Practice #17\\\", \\\"Practice #23\\\",\\n        \\\"Practice #26 \\u00e2\\u00ad\\u0090 DOK-3 DRIVER\\\",\\n    ]\\n    for label, q in zip(labels, items):\\n        bank_item_block(doc, q, label=f\\\"{label} ({q['id']})\\\", space_after_inches=0.3)\\n        add_callout(doc, \\\"\\u00e2\\u0153\\u2026  ANSWER / ANTICIPATED TALK\\\",\\n                    [q.get(\\\"notes\\\") or \\\"(no answer key \\u00e2\\u20ac\\u201d verify before class)\\\"],\\n                    color_hex=\\\"D9EAD3\\\")\\n\\n    ps.framework_phase_header(\\n        doc,\\n        phase=\\\"Share / Summary\\\",\\n        framework_tag=\\\"academic conversation + Wed bridge\\\",\\n        dok=\\\"2\\\",\\n        minutes=5,\\n        teacher_does=[\\n            \\\"Cold-call 1 pair to present Ram\\u00c3\\u00b3n's Part A (direct) + Part B (inverse) using sentence frame.\\\",\\n            \\\"Class signals thumbs. Write the direct-vs-inverse test on board.\\\",\\n    