hes.items():\\\\n        target = by_id.get(pid)\\\\n        if target is None:\\\\n            missing.append((pid, patch.get(\\\\\\\"_source_file\\\\\\\", \\\\\\\"?\\\\\\\")))\\\\n            continue\\\\n        for f in V2_FIELDS:\\\\n            if f in patch:\\\\n                target[f] = patch[f]\\\\n        if patch.get(\\\\\\\"notes\\\\\\\") and not target.get(\\\\\\\"notes\\\\\\\"):\\\\n            target[\\\\\\\"notes\\\\\\\"] = patch[\\\\\\\"notes\\\\\\\"]\\\\n        applied += 1\\\\n\\\\n    print(f\\\\\\\"Patched {applied}/{len(patches)} tagged items into registry.\\\\\\\")\\\\n    if missing:\\\\n        print(f\\\\\\\"\\\\\\\\n{len(missing)} pilot rows missing from registry:\\\\\\\")\\\\n        for pid, src in missing:\\\\n            print(f\\\\\\\"  - {pid}  (from {src})\\\\\\\")\\\\n\\\\n    if args.dry_run:\\\\n        print(\\\\\\\"(dry run \\\\u00e2\\\\u20ac\\\\u201d no file written)\\\\\\\")\\\\n        return 0\\\\n\\\\n    out = \\\\\\\"\\\\\\\\n\\\\\\\".join(json.dumps(r, ensure_ascii=False) for r in registry) + \\\\\\\"\\\\\\\\n\\\\\\\"\\\\n    REGISTRY.write_text(out, encoding=\\\\\\\"utf-8\\\\\\\")\\\\n    print(f\\\\\\\"Wrote {REGISTRY}.\\\\\\\")\\\\n    return 0\\\\n\\\\n\\\\nif __name__ == \\\\\\\"__main__\\\\\\\":\\\\n    sys.exit(main())\\\\n\\\\n succeeded in 535ms:\\\\n# Skill tokens \\\\u00e2\\\\u20ac\\\\u201d glossary\\\\n\\\\nAtomic moves. One token = one thing a student either can or cannot do, independent of topic/lesson wrapper. Kebab-case. Append as new ones emerge during the dry-run; never rename silently (breaks the DAG).\\\\n\\\\n## Seeded from Lesson 5-1 pilot\\\\n\\\\n| Token | Definition |\\\\n|---|---|\\\\n| `evaluate-nth-root` | Given a numeric radicand and integer index, produce the real root(s). |\\\\n| `count-real-nth-roots` | State how many real nth roots a given number has (rule by parity of index + sign of radicand). |\\\\n| `convert-radical-to-rational-exp` | Rewrite \\\\u00e2\\\\u02c6\\\\u0161[n]{x^m} as